// ── HERO ──────────────────────────────────────────────────────────
import React from 'react';
const heroStyles = {
  hero: {
    position: "relative",
    minHeight: "92vh",
    width: "100%",
    background: `url(${process.env.PUBLIC_URL}/assets/hero-bg.png) center 35% / cover no-repeat`,
    display: "flex",
    flexDirection: "column",
    justifyContent: "center",
    alignItems: "center",
    overflow: "hidden",
  },
};

function HeroButton({ kind, img, label, sub, onClick }) {
  const [hover, setHover] = React.useState(false);
  const isPager = kind === "pager";
  return (
    <button
      className={`hero-btn hero-btn--${kind}`}
      onClick={onClick}
      onMouseEnter={() => setHover(true)}
      onMouseLeave={() => setHover(false)}
      aria-label={label}
    >
      <span className="hero-btn__art">
        <img src={img} alt={label} draggable="false" />
      </span>
      <span className="hero-btn__tag" style={{
        background: isPager ? "#00BF63" : "#00ABFF",
        color: "var(--cnp-white)",
      }}>
        <span className="horizon">{label}</span>
        <em>{sub}</em>
      </span>
    </button>
  );
}

function Hero() {
  const scrollTo = (id) => {
    const el = document.getElementById(id);
    if (el) window.scrollTo({ top: el.offsetTop, behavior: "smooth" });
  };
  return (
    <section className="section hero" id="top" style={heroStyles.hero} data-screen-label="Hero">
      <div className="hero__scrim" />
      <div className="hero__content">
        <p className="hero__hello reveal">"Hello, World!"</p>
        <h1 className="hero__head horizon reveal" style={{ animationDelay: "120ms" }}>
          "In a world of<br/>infinite <br/>
          generation, taste becomes power."
        </h1>
      </div>

      <div className="hero__buttons">
        <HeroButton
          kind="pager"
          img={`${process.env.PUBLIC_URL}/assets/btn-contacto.png`}
          label="Contacto"
          sub="Send us a message"
          onClick={() => scrollTo("contacto")}
        />
        <HeroButton
          kind="pet"
          img={`${process.env.PUBLIC_URL}/assets/btn-game.png`}
          label="Game"
          sub="Play the game"
          onClick={() => {}}
        />
      </div>


    </section>
  );
}

export default Hero;
